# đơn vị và số phần, áp dụng sau cùng
REGEX = [
    (r"Phần (\d+) · ", r"Part \1 · "),
    (r"phần (\d+)", r"Part \1"),
    (r"tỷ đồng", "VND bn"),
    (r" tỷ\b", " bn"),
]
KEEP = ["Đất Xanh", "Hải Phát", "Khang Điền", "Phát Đạt", "Quốc Cường Gia Lai"]  # tên riêng công ty


def translate(html):
    i = html.find("const D=")
    j = html.find("\n", i)
    data, html = html[i:j], html[:i] + "\0DATA\0" + html[j:]
    for vi, en in PAIRS:
        html = html.replace(vi, en)
    for pat, rep in REGEX:
        html = re.sub(pat, rep, html)
    # kiểm tra sót chữ tiếng Việt (bỏ qua tên công ty)
    probe = html
    for k in KEEP:
        probe = probe.replace(k, "")
    left = sorted(set(re.findall(r"[^\s<>'\"`]*[àáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđĐ][^\s<>'\"`]*", probe, re.I)))
    if left:
        sys.exit("Còn sót chữ tiếng Việt: " + " | ".join(left[:60]))
    return html.replace("\0DATA\0", data)


if __name__ == "__main__":
    src, out = sys.argv[1], sys.argv[2]
    html = translate(open(src, encoding="utf-8").read().replace("\r\n", "\n"))
    open(out, "w", encoding="utf-8", newline="\n").write(html)
    print(f"Đã ghi {out} ({len(html) / 1024:.0f} KB)")
